INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Matrixorganisation immer nur in großen IT-Firmen genutzt wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in kleineren Firmen möglich"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich eine Matrixorganisation in einer IT-Firma einführe?', 3, '[{"text": "Klare Verantwortlichkeiten", "correct": true, "because": "Vermeidet Konflikte"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Struktur zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale charakterisieren eine Matrixorganisation in der IT?', 5, '[{"text": "Doppelte Berichtslinien", "correct": true, "because": "Funktional und projektbezogen"}, {"text": "Flexibilität", "correct": true, "because": "Passt sich Projekten an"}, {"text": "Büromöbel", "correct": false, "because": "Kein Merkmal"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Matrixorganisation kombiniert Hierarchien. b) Sie ist immer chaotisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht zwangsläufig chaotisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Matrixorganisation für eine IT-Firma plane?', 4, '[{"text": "Kommunikationswege", "correct": false, "because": "Wichtig für Koordination"}, {"text": "Rollenklarheit", "correct": false, "because": "Vermeidet Konflikte"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Organisationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Matrixorganisation immer zwei Hierarchieebenen hat?', 2, '[{"text": "Ja", "correct": true, "because": "Funktional und projektbezogen"}, {"text": "Nein", "correct": false, "because": "Grundprinzip der Matrix"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Matrixorganisation in der IT?', 3, '[{"text": "Effiziente Ressourcennutzung", "correct": true, "because": "Optimiert Teams"}, {"text": "Schnellste Struktur", "correct": false, "because": "Effektivität zählt"}, {"text": "Weniger Kommunikation", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Matrixorganisation in der IT?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Passt sich Projekten an"}, {"text": "Spezialisierung", "correct": true, "because": "Nutzt Expertise"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Eine Matrixorganisation fördert Zusammenarbeit. b) Sie ist immer ineffizient. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht zwangsläufig ineffizient"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Matrixorganisation in der IT einzuführen?', 4, '[{"text": "Projektmanagement", "correct": false, "because": "Koordiniert Teams"}, {"text": "Kommunikationsplan", "correct": false, "because": "Sichert Ablauf"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Organisationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Matrixorganisation immer chaotisch?', 2, '[{"text": "Nein", "correct": true, "because": "Mit Struktur effizient"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine Matrixorganisation in der IT?', 4, '[{"text": "Komplexität", "correct": true, "because": "Erhöht Koordinationsaufwand"}, {"text": "Rollenkonflikte", "correct": true, "because": "Doppelte Berichtslinien"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Matrixorganisation nur für Projekte geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Dauerstrukturen"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um eine Matrixorganisation effektiv zu gestalten?', 3, '[{"text": "Klar definierte Rollen", "correct": true, "because": "Vermeidet Konflikte"}, {"text": "Schnellste Einführung", "correct": false, "because": "Struktur wichtiger"}, {"text": "Bunte Organigramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Matrixorganisation nutzt funktionale Expertise. b) Sie ist immer hierarchiefrei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hat Hierarchien"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei einer Matrixorganisation?', 5, '[{"text": "Kommunikation", "correct": true, "because": "Sichert Koordination"}, {"text": "Ressourcennutzung", "correct": true, "because": "Optimiert Teams"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich eine Matrixorganisation für eine IT-Firma plane?', 3, '[{"text": "Projektziele", "correct": false, "because": "Bestimmen Struktur"}, {"text": "Rollenverteilung", "correct": false, "because": "Vermeidet Konflikte"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Organisationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Matrixorganisation immer komplex?', 3, '[{"text": "Ja", "correct": true, "because": "Mehrdimensionale Struktur"}, {"text": "Nein", "correct": false, "because": "Mit Planung effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Matrixorganisation nur für IT geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Branchen"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für eine Matrixorganisation?', 4, '[{"text": "Klare Kommunikation", "correct": true, "because": "Sichert Effizienz"}, {"text": "Schnellste Einführung", "correct": false, "because": "Struktur zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
